// UsedByContainsFold applies the ContainsFold predicate on the "used_by" field.
func UsedByContainsFold(v string) predicate.SubscriptionChoice {
	return predicate.SubscriptionChoice(sql.FieldContainsFold(FieldUsedBy, v))
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.SubscriptionChoice) predicate.SubscriptionChoice {
	return predicate.SubscriptionChoice(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.SubscriptionChoice) predicate.SubscriptionChoice {
	return predicate.SubscriptionChoice(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.SubscriptionChoice) predicate.SubscriptionChoice {
	return predicate.SubscriptionChoice(sql.NotPredicates(p))
}
